package com.mannvaasam.repo; import com.mannvaasam.model.*; import org.springframework.data.jpa.repository.*; import java.util.*; public interface OrderRepository extends JpaRepository<Order,Long>{List<Order> findByBuyerOrderByCreatedAtDesc(User buyer); List<Order> findBySellerOrderByCreatedAtDesc(User seller); Optional<Order> findByOrderNumber(String orderNumber); Optional<Order> findByIdAndBuyer(Long id,User buyer); Optional<Order> findByIdAndSeller(Long id,User seller);}